<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';import {lineupFit} from './engine/lineup-fit.mjs';import {pick,BP_STEPS,applyBpAction,NBA_STEPS,undoDraft,rankBans,playerTraits} from './engine/draft';import type {Side,DraftRecord} from './engine/draft';import {metricsForPosition,metricValue,metricSources} from './engine/position-metrics';import type {Metric} from './engine/position-metrics';
type Player={id:number,name:string,team:string,position:string,heightCm:number,weightKg?:number|null,insideSamples?:{season:number,possessions:number}[],rimSamples?:{season:number,attempts:number,allowed:number,baseline:number}[],value:number|null,pts:number,reb:number,ast:number,stl:number,tov:number,ts:number,per:number,astTo:number,blk:number,seasons?:{season:string,gp:number,pts:number,reb:number,ast:number,blk:number,stl:number,tov:number,per:number,points:number,fga:number,fta:number}[]};
const bpEnabled=ref(false),bpHistory=ref<DraftRecord[]>([]),normalHistory=ref<DraftRecord[]>([]),feedback=ref<{side:Side,kind:'ban'|'pick',name:string}|null>(null);let feedbackTimer:ReturnType<typeof setTimeout>|undefined;const feedbackQueue:{side:Side,kind:'ban'|'pick',name:string}[]=[];const shareImage=ref(''),shareMessage=ref(''),sharePosition=ref(0);const players=ref<Player[]>([]),screen=ref('setup'),mode=ref('human'),side=ref('blue'),home=ref<number[]>([]),away=ref<number[]>([]),search=ref(''),position=ref('全部'),team=ref('全部'),sort=ref('default'),busy=ref(false),reason=ref(''),review=ref<any>(null),reviewLoading=ref(false),reviewError=ref(''),error=ref('');
const position5=(p:Player)=>p.position==='C'?'C':p.position==='G'?(p.ast>=4?'PG':'SG'):(p.heightCm>=205?'PF':'SF');
const positionLabels=['控球后卫','得分后卫','小前锋','大前锋','中锋'];
const dragging=ref<{side:number,index:number}|null>(null),dragOver=ref<number|null>(null);
function dragStart(event:DragEvent,sideIndex:number,index:number){dragging.value={side:sideIndex,index};if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(index))}}
function dragEnd(){dragging.value=null;dragOver.value=null}
function dragEnter(event:DragEvent,sideIndex:number,index:number,ids:number[]){if(dragging.value?.side!==sideIndex||index>=ids.length)return;event.preventDefault();dragOver.value=index;if(event.dataTransfer)event.dataTransfer.dropEffect='move'}
function dropPlayer(event:DragEvent,sideIndex:number,index:number,ids:number[]){event.preventDefault();if(dragging.value?.side===sideIndex&&index<ids.length){const from=dragging.value.index;[ids[from],ids[index]]=[ids[index],ids[from]]}dragEnd()}
function movePlayer(ids:number[],index:number,delta:number){const target=index+delta;if(target<0||target>=ids.length)return;[ids[index],ids[target]]=[ids[target],ids[index]]}
const steps=NBA_STEPS;const turn=computed(()=>bpEnabled.value?bpHistory.value.length:home.value.length+away.value.length);const totalSteps=computed(()=>bpEnabled.value?BP_STEPS.length:steps.length);const finished=computed(()=>turn.value===totalSteps.value);const currentAction=computed(()=>bpEnabled.value?BP_STEPS[turn.value]:{side:steps[turn.value],kind:'pick' as const});const current=computed(()=>currentAction.value?.side);const used=computed(()=>new Set([...home.value,...away.value,...bpHistory.value.map(x=>x.playerId)]));const banHistory=computed(()=>bpHistory.value.filter(x=>x.kind==='ban'));const pickOrder=(ix:number,n:number):number|undefined=>bpEnabled.value?BP_STEPS.map((s,i)=>s.kind==='pick'&&s.side===(ix?'red':'blue')?BP_STEPS.slice(0,i+1).filter(x=>x.kind==='pick').length:0).filter(Boolean)[n-1]:steps.map((s,i)=>s===(ix?'red':'blue')?i+1:0).filter(Boolean)[n-1];
const pool=computed(()=>players.value.filter(p=>!used.value.has(p.id)&&p.name.toLowerCase().includes(search.value.toLowerCase())&&(position.value==='全部'||position5(p)===position.value)&&(team.value==='全部'||p.team===team.value)).sort((a,b)=>sort.value==='default'?((b.value ?? -Infinity)-(a.value ?? -Infinity) || a.name.localeCompare(b.name)):(Number((b as any)[sort.value])||0)-(Number((a as any)[sort.value])||0)));const teams=computed(()=>[...new Set(players.value.map(p=>p.team))].sort());const person=(id:number)=>players.value.find(p=>p.id===id);const names=['持球创造','外线空间','篮下防守（估计）','外线防守（估计）','组织串联','篮板保护','进攻效率','阵容适配'];const keys=['creation','spacing','rim','perimeter','playmaking','rebounding','efficiency','fit'];
function matchupValue(id:number,stat:Metric,positionIndex:number){const bucket=positionIndex<2?'G':positionIndex<4?'F':'C';return metricValue(person(id),stat.key,players.value.filter(p=>p.position===bucket))}
function statText(value:number|null,_stat:Metric){return value===null?'暂无数据':value.toFixed(0)}
type TeamMetric={key:string,label:string,description:string};
const teamMetrics:TeamMetric[]=[
{key:'shooting',label:'外线投射',description:'每36分钟三分出手与三分命中率的五人平均，各占一半；分别按0–8次、25%–45%映射。'},
{key:'drives',label:'突破效率',description:'球员突破得分除以突破次数；至少三名球员有每赛季50次突破样本，按0.3–1.1分映射，不包含突破分球贡献。'},
{key:'perimeter',label:'外线防守',description:'防守三分命中率相对对手常态的差值，至少三名球员各有50次防守出手，按-10至+10个百分点映射；不代表完整外线防守。'},
{key:'rim',label:'内线防守',description:'使用有篮下防守追踪数据球员的命中率差平均值，至少三人有数据；按-10至+10个百分点映射。未区分协防与对位，不代表实际共同防守表现。'},
{key:'rebounding',label:'篮板保护',description:'五人每36分钟防守篮板平均值按0–10个映射；未按篮板机会调整。'},
{key:'playmaking',label:'进攻组织',description:'场均助攻按0–8次映射；若至少三人有潜在助攻追踪，加入每36分钟潜在助攻（0–16次映射），两项各占50%。不足三人时仅按助攻；不能完整衡量组织能力。'},
{key:'efficiency',label:'进攻效率',description:'五人真实命中率平均值按45%–70%映射；并非实际球队进攻效率。'},
{key:'defense',label:'防守投篮',description:'球员防守投篮命中率相对对手常态的差值，仅为防守投篮参考，不是五人共同上场的每百回合防守效率；至少三名球员有样本。'},
{key:'fit',label:'球权适配',description:'基于组织点、高持球负荷人数和射手数量的规则推演；未衡量实际无球适配，不代表共同上场表现。'}];
function teamMetricValue(ids:number[],key:string):number|null {const team=ids.map(person);if(team.length!==5||team.some(p=>!p))return null;const ps=team as any[];const avg=(get:(p:any)=>number|undefined)=>{const xs=ps.map(get);return xs.some(x=>typeof x!=='number'||!Number.isFinite(x))?null:(xs as number[]).reduce((a,b)=>a+b,0)/xs.length};const norm=(x:number,min:number,max:number)=>Math.max(0,Math.min(100,(x-min)/(max-min)*100));let value:number|null=null;if(key==='shooting'){const attempts=avg(p=>p.per36?.tpa),pct=avg(p=>p.tpPct);if(attempts!==null&&pct!==null)value=.5*norm(attempts,0,8)+.5*norm(pct,.25,.45)}else if(key==='playmaking'){const x=avg(p=>p.ast);const potential=ps.map(p=>p.potentialMetric).filter((v:any)=>typeof v==='number'&&Number.isFinite(v));if(x!==null)value=potential.length>=3?.5*norm(x,0,8)+.5*norm(potential.reduce((a:number,b:number)=>a+b,0)/potential.length,0,16):norm(x,0,8)}else if(key==='rebounding'){const x=avg(p=>p.dreb36);if(x!==null)value=norm(x,0,10)}else if(key==='drives'||key==='perimeter'||key==='defense'){const field=key==='drives'?'driveMetric':key==='perimeter'?'perimeterMetric':'defenseMetric';const xs=ps.map(p=>p[field]).filter((x:any)=>typeof x==='number'&&Number.isFinite(x));if(xs.length>=3)value=norm(xs.reduce((a:number,b:number)=>a+b,0)/xs.length,key==='drives'?.3:-.1,key==='drives'?1.1:.1)}else if(key==='rim'){const xs=ps.map(p=>p.rimDifferential).filter((x:any)=>typeof x==='number'&&Number.isFinite(x));if(xs.length>=3)value=norm(xs.reduce((a:number,b:number)=>a+b,0)/xs.length,-.1,.1)}else if(key==='efficiency'){const x=avg(p=>p.ts);if(x!==null)value=norm(x,.45,.70)}else if(key==='fit'){if(ps.every(p=>Number.isFinite(p.ast)&&Number.isFinite(p.per36?.load)&&Number.isFinite(p.per36?.tpa)&&Number.isFinite(p.tpPct))){const f=lineupFit(ps);value=(ps.some(p=>p.ast>=4)?30:0)+30*Math.min(1,f.shooters.length/2)+(f.high.length===1?40:f.high.length===0?20:20)}}return value===null?null:Math.round(value)}
const metricGroups=[{label:'进攻',keys:['shooting','drives','playmaking','efficiency']},{label:'防守与篮板',keys:['perimeter','rim','rebounding','defense']},{label:'阵容配合',keys:['fit']}];
function metricByKey(key:string){return teamMetrics.find(m=>m.key===key)!}
function metricLead(key:string):'home'|'away'|'even'|'missing'{const h=teamMetricValue(home.value,key),a=teamMetricValue(away.value,key);return h===null||a===null?'missing':Math.abs(h-a)<5?'even':h>a?'home':'away'}
function teamMetricText(v:number|null){return v===null?'暂无数据':String(v)}
function missingReason(id:number,stat:Metric,index:number){const player=person(id);if(!player)return '球员数据缺失';if(!stat.components.length)return '指标未接入';const missing=metricSources(player,stat).filter(p=>p.value===null);if(missing.length)return missing.some(p=>/Ppp|Differential/.test(p.key))?'追踪数据缺失或样本不足':'所需数据缺失';const bucket=index<2?'G':index<4?'F':'C';const pool=players.value.filter(p=>p.position===bucket);if(metricValue(player,stat.key,pool)===null)return '同组可用样本不足';return ''}
function playerRadarValues(id:number,positionIndex:number){return metricsForPosition(positionIndex).map(stat=>matchupValue(id,stat,positionIndex))}
const playerPoint=(i:number,value:number)=>{const angle=-Math.PI/2+i*2*Math.PI/8,r=value*1.18;return [180+Math.cos(angle)*r,155+Math.sin(angle)*r]};
const playerPoly=(values:number[])=>values.map((v,i)=>playerPoint(i,v).join(',')).join(' ');
function playerSegments(id:number,positionIndex:number){const values=playerRadarValues(id,positionIndex);return values.flatMap((v,i)=>{const next=values[(i+1)%8];return v===null||next===null?[]:[{a:playerPoint(i,v),b:playerPoint((i+1)%8,next)}]})}

const radarPoint=(i:number,value:number)=>{const angle=-Math.PI/2+i*2*Math.PI/8,r=value*1.18;return [180+Math.cos(angle)*r,155+Math.sin(angle)*r]};
const radarPoly=(values:number[])=>values.map((v,i)=>radarPoint(i,v).join(',')).join(' ');
const radarValues=(which:'home'|'away')=>keys.map(k=>review.value?.mode==='ai'?review.value.dimensionScores[which][k]:k==='fit'?Math.max(0,Math.min(100,60+(review.value.diagnostics[which].counts.spacing>=3?10:0)-(review.value.diagnostics[which].weak.some((v:string)=>v.includes('球权过载'))?20:0)-(review.value.diagnostics[which].counts.spacing<=1?15:0))):review.value.diagnostics[which].counts[k]*20);

onMounted(async()=>{try{let d=await fetch('/api/players').then(r=>r.json());players.value=d.players;if(!players.value.length)error.value='数据未就绪，请先运行 npm run players:fetch'}catch{error.value='无法连接服务，请检查后端'}});
const activeRoster=computed(()=> (current.value==='blue'?home.value:away.value).map(id=>person(id)).filter((p):p is Player=>!!p));
const currentFit=computed(()=>lineupFit(activeRoster.value));
function prepareShare(){if(!review.value)return;const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=980;const c=canvas.getContext('2d');if(!c)return;c.fillStyle='#101c2b';c.fillRect(0,0,1200,980);c.fillStyle='#ef7957';c.fillRect(0,0,1200,12);c.fillStyle='#e8eee9';c.font='bold 32px sans-serif';c.fillText('COURTSIDE / DRAFT',60,74);c.font='bold 46px sans-serif';c.fillText('首发阵容对决',60,150);c.font='bold 28px sans-serif';c.fillStyle='#ee8263';c.fillText('主队',60,230);c.fillStyle='#72c5ce';c.fillText('客队',650,230);c.font='26px sans-serif';[home.value,away.value].forEach((ids,sideIndex)=>ids.forEach((id,i)=>{c.fillStyle='#e8efed';c.fillText(`${['PG','SG','SF','PF','C'][i]}   ${person(id)?.name||'—'}`,sideIndex?650:60,290+i*62,500)}));c.fillStyle='#e9efeb';c.font='bold 30px sans-serif';c.fillText(`主队 ${review.value.verdict.blueWinRate}%   /   ${review.value.verdict.redWinRate}% 客队`,60,680);c.font='21px sans-serif';c.fillStyle='#a5b9b7';c.fillText('比赛倾向为主观估计，并非统计预测',60,722);c.fillStyle='#f0ae8d';c.font='bold 24px sans-serif';c.fillText(`对位 · ${positionLabels[sharePosition.value]}`,60,792);c.fillStyle='#e9efeb';c.font='25px sans-serif';c.fillText(`${person(home.value[sharePosition.value])?.name||'—'}  vs  ${person(away.value[sharePosition.value])?.name||'—'}`,60,838,1080);c.font='18px sans-serif';c.fillStyle='#a5b9b7';c.fillText('2024–26 常规赛数据 · 位置由选秀阵容指定',60,923);shareImage.value=canvas.toDataURL('image/png');shareMessage.value=''}
function downloadShare(){const a=document.createElement('a');a.href=shareImage.value;a.download='courtside-draft.png';a.click()}
async function shareResult(){try{const blob=await (await fetch(shareImage.value)).blob();const file=new File([blob],'courtside-draft.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})&&navigator.share){await navigator.share({title:'阵容对决',files:[file]});return}downloadShare();shareMessage.value='已准备图片下载，可保存后分享。'}catch(e){if((e as Error).name!=='AbortError')shareMessage.value='分享不可用，请使用保存图片。'}}
const history=computed(()=>bpEnabled.value?bpHistory.value:normalHistory.value);
const canUndo=computed(()=>!busy.value&&!reviewLoading.value&&history.value.length>0&&(mode.value==='human'||history.value.some(x=>x.side===side.value)));
function clearFeedback(){clearTimeout(feedbackTimer);feedbackQueue.length=0;feedback.value=null}
function showNextFeedback(){const next=feedbackQueue.shift();if(!next){feedback.value=null;return}feedback.value=next;feedbackTimer=setTimeout(showNextFeedback,1600)}
function showActionFeedback(side:Side,kind:'ban'|'pick',id:number){feedbackQueue.push({side,kind,name:person(id)?.name??''});if(feedbackQueue.length>5)feedbackQueue.shift();if(!feedback.value)showNextFeedback()}
onUnmounted(clearFeedback);
function undoLast(){if(!canUndo.value)return;const removed=undoDraft(history.value,home.value,away.value,mode.value==='ai'?side.value as Side:null);if(removed.length){review.value=null;reviewError.value='';error.value='';reason.value=mode.value==='ai'&&removed.length>1?`已撤销你的操作和随后 ${removed.length-1} 次 AI 操作`:'已撤销上一步';clearFeedback()}}
const bpHighlights=computed(()=>{const actions=bpHistory.value;return [0,1].flatMap(round=>{const subset=actions.slice(round?10:0,round?16:4).filter(x=>x.kind==='ban');return (['blue','red'] as Side[]).flatMap(side=>{const eligible=subset.filter(x=>x.side===side).sort((a,b)=>(person(b.playerId)?.value??-Infinity)-(person(a.playerId)?.value??-Infinity));const entry=eligible[0];if(!entry)return [];const index=actions.indexOf(entry),prior=actions.slice(0,index),opponents=prior.filter(x=>x.kind==='pick'&&x.side!==side).map(x=>person(x.playerId)).filter((p):p is Player=>!!p),banned=person(entry.playerId);if(!banned)return [];const next=actions.slice(index+1).find(x=>x.kind==='pick'&&x.side!==side),traits=playerTraits(banned),needs=opponents.length?lineupFit(opponents).needs.slice(0,2):[];return [{key:`${round}-${side}`,side,name:banned.name,nextPick:next?person(next.playerId)?.name:null,round:round+1,context:opponents.length?`禁用前对方已选：${opponents.map(p=>p.name).join('、')}`:'禁用时对方尚未选人',needs:needs.length?needs.join('、'):'阵容尚未形成，无法判断具体需求',traits:traits.length?traits.join('、'):'现有标签不足以判断主要作用'}]})})});
function doAction(playerId:number,expectedSide:Side){if(finished.value||current.value!==expectedSide||used.value.has(playerId)||!person(playerId))return false;const kind=currentAction.value.kind;const applied=bpEnabled.value?applyBpAction(bpHistory.value,home.value,away.value,expectedSide,kind,playerId):pick(home.value,away.value,expectedSide,playerId);if(!applied)return false;if(!bpEnabled.value)normalHistory.value.push({side:expectedSide,kind:'pick',playerId});showActionFeedback(expectedSide,kind,playerId);return true}
function select(p:Player){if(busy.value||finished.value||!current.value)return;const acting=current.value;if(!doAction(p.id,acting))return;reason.value='';if(mode.value==='ai'&&!finished.value&&current.value!==side.value)ai()}
async function ai(){if(busy.value||finished.value||!current.value)return;busy.value=true;const acting=current.value,kind=currentAction.value.kind;try{let playerId:number,aiReason:string;if(kind==='ban'){const other=(acting==='blue'?away.value:home.value).map(person).filter((p):p is Player=>!!p),own=(acting==='blue'?home.value:away.value).map(person).filter((p):p is Player=>!!p),ranking=rankBans(players.value.filter(p=>!used.value.has(p.id)),other,turn.value,own);if(!ranking.length)throw Error('没有可禁用的球员');const shortlist=ranking.slice(0,Math.min(4,ranking.length)),chosen=shortlist[Math.floor(Math.random()*shortlist.length)];playerId=chosen.player.id;aiReason=chosen.reason+'；当时同位置可能替代：'+(chosen.alternatives.map(p=>p.name).join('、')||'暂无')+'（位置估算）'}else{let r=await fetch('/api/ai-draft',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({home:home.value,away:away.value,side:acting,available:players.value.filter(p=>!used.value.has(p.id)).map(p=>p.id)})});let d=await r.json();if(!r.ok)throw new Error(d.error);playerId=d.playerId;aiReason=d.reason||'完成选择'}if(!doAction(playerId,acting))throw new Error('AI 操作无效，请重试');reason.value=`AI ${kind==='ban'?'禁用':'选择'} ${person(playerId)?.name??''}：${aiReason}`;}catch(e){error.value=String(e)}finally{busy.value=false}if(!finished.value&&current.value!==side.value&&mode.value==='ai'&&!error.value)ai()}
function start(){error.value='';screen.value='draft';if(mode.value==='ai'&&current.value!==side.value)ai()}
function resetDraft(){screen.value='setup';home.value=[];away.value=[];bpHistory.value=[];normalHistory.value=[];clearFeedback();reason.value='';error.value=''}
async function showReview(){if(reviewLoading.value)return;reviewLoading.value=true;reviewError.value='';review.value=null;try{let r=await fetch('/api/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({home:home.value,away:away.value})});let data=await r.json();if(!r.ok)throw new Error(data.error||'复盘请求失败');review.value=data}catch(e){reviewError.value=e instanceof Error?e.message:'复盘请求失败，请重试'}finally{reviewLoading.value=false}}

</script>
<template><div class="app"><header><div class="brand">COURTSIDE <b> / DRAFT</b></div><div class="tag">2024—26 REGULAR SEASONS</div><button v-if="screen==='draft'" :disabled="busy" @click="resetDraft">重新开始</button></header><main v-if="screen==='setup'" class="setup cover cover-new"><div class="cover-art" aria-hidden="true"><div class="new-arena-glow"></div><div class="new-court-lines"></div><div class="new-back-type">DRAFT<br>NIGHT</div><img class="cover-player player-left" src="/headshots/3975.png" @error="($event.target as HTMLImageElement).style.display='none'"><img class="cover-player player-right" src="/headshots/3112335.png" @error="($event.target as HTMLImageElement).style.display='none'"><img class="cover-player player-main" src="/headshots/4278073.png" @error="($event.target as HTMLImageElement).style.display='none'"><div class="new-art-label"><span>THE 2024–26 SEASONS</span><b>YOUR COURT.<br>YOUR RULES.</b></div></div><div class="cover-text"><div class="new-season"><span></span> 2024–26 REGULAR SEASONS <i>/</i> NBA DRAFT SIMULATOR</div><h1 class="new-title">组建你的<br><em>首发阵容<span>.</span></em></h1><p class="new-intro">{{players.length}} 位球员，10 次选择。<br>你的首发五人，能走到最后吗？</p><div class="new-setup"><div class="new-section-heading"><span>GAME MODE</span><b>选择对战方式</b></div><div class="options"><button :class="{selected:mode==='human'}" @click="mode='human'"><span class="new-option-icon">VS</span><span class="new-option-copy"><strong>双人对战</strong><small>和朋友轮流选人</small></span><span class="new-check">✓</span></button><button :class="{selected:mode==='ai'}" @click="mode='ai'"><span class="new-option-icon">AI</span><span class="new-option-copy"><strong>挑战 AI</strong><small>对战智能选秀对手</small></span><span class="new-check">✓</span></button></div><div class="bp-option"><div><strong>禁选模式</strong><small>两轮禁用，共禁用 10 位球员</small></div><button type="button" role="switch" :aria-checked="bpEnabled" :class="{on:bpEnabled}" @click="bpEnabled=!bpEnabled">{{bpEnabled?'已开启':'未开启'}}</button></div><div class="new-bottom-controls"><div><div class="new-section-heading"><span>YOUR SIDE</span><b>选择执方</b></div><div class="sidechoice"><button :class="{selected:side==='blue'}" @click="side='blue'">主队 <small>先选</small></button><button :class="{selected:side==='red'}" @click="side='red'">客队 <small>后选</small></button></div></div><button class="primary cover-cta" :disabled="!!error" @click="start"><span>开始选秀</span><span>↗</span></button></div><p v-if="error" class="error">{{error}}</p></div></div><div class="cover-bottom"><span>COURTSIDE / DRAFT</span><span>10 PICKS &nbsp; · &nbsp; 2 TEAMS &nbsp; · &nbsp; 1 WINNER</span><span>2024—26 SEASONS</span></div></main><main v-else class="draft"><div class="progress" :class="finished ? 'complete' : current==='blue' ? 'home-turn' : 'away-turn'"><div><small>{{bpEnabled?'BAN / PICK':'THE DRAFT'}}</small><h2>{{finished?'选秀完成':`第 ${turn+1} 手 · ${current==='blue'?'主队':'客队'}${currentAction.kind==='ban'?'禁用':'选择'}`}}</h2></div><div v-if="bpEnabled" class="ban-board" aria-label="双方禁用球员"><div v-for="teamSide in ['blue','red']" :key="teamSide" class="ban-board-side" :class="teamSide==='blue'?'ban-board-home':'ban-board-away'"><strong>{{teamSide==='blue'?'主队':'客队'}}禁用 <span>{{banHistory.filter(x=>x.side===teamSide).length}} / 5</span></strong><div class="ban-board-players"><div v-for="n in 5" :key="n" class="ban-player" :title="person(banHistory.filter(x=>x.side===teamSide)[n-1]?.playerId)?.name || '待禁用'"><template v-if="banHistory.filter(x=>x.side===teamSide)[n-1]"><img :src="`/headshots/${banHistory.filter(x=>x.side===teamSide)[n-1].playerId}.png`" alt=""><span>{{person(banHistory.filter(x=>x.side===teamSide)[n-1].playerId)?.name}}</span></template><template v-else><div class="ban-empty">—</div><span>待禁用</span></template></div></div></div></div><button class="undo-button" :disabled="!canUndo" @click="undoLast" :title="mode==='ai'?'撤销你的上一步及其后 AI 操作':'撤销上一步'">↶ 撤销</button><button v-if="finished" class="primary" :disabled="reviewLoading" @click="showReview">{{reviewLoading ? '正在生成复盘…' : '查看阵容复盘 →'}}</button></div><div v-if="feedback" class="action-feedback" :class="[feedback.side==='blue'?'feedback-home':'feedback-away',feedback.kind==='ban'?'feedback-ban':'feedback-pick']" role="status"><span>{{feedback.kind==='ban'?'BAN':'PICK'}}</span><strong>{{feedback.side==='blue'?'主队':'客队'}}{{feedback.kind==='ban'?'禁用':'选择'}} {{feedback.name}}</strong></div><div class="layout"><section v-for="(ids,ix) in [home,away]" :key="ix" class="roster" :class="{active:!finished && current===(ix?'red':'blue'),'team-home':ix===0,'team-away':ix===1}"><div class="panelhead"><small>{{ix?'AWAY TEAM':'HOME TEAM'}}</small><h2>{{ix?'客队':'主队'}} <span>{{ids.length}} / 5</span></h2><p v-if="!finished && current===(ix?'red':'blue')" class="turn-badge">● 正在{{currentAction.kind==='ban'?'禁用':'选人'}}</p><p v-else class="reorder-hint">拖动球员调整位置</p></div><div v-for="n in 5" :key="n" class="slot" :class="{filled:ids[n-1],dragging:dragging?.side===ix && dragging?.index===n-1,'drag-target':dragging?.side===ix && dragOver===n-1}" :draggable="!!ids[n-1]" @dragstart="dragStart($event,ix,n-1)" @dragover="dragEnter($event,ix,n-1,ids)" @dragleave="dragOver=null" @drop="dropPlayer($event,ix,n-1,ids)" @dragend="dragEnd"><span class="slot-position">{{['PG','SG','SF','PF','C'][n-1]}}</span><template v-if="ids[n-1]"><img :src="`/headshots/${ids[n-1]}.png`" @error="($event.target as HTMLImageElement).style.display='none'"><div><b>{{person(ids[n-1])?.name}}</b><small>{{person(ids[n-1])?.team}} · {{positionLabels[n-1]}}</small></div><span class="drag-handle" aria-hidden="true">⠿</span><div class="move-controls"><button :disabled="n===1" :aria-label="`将 ${person(ids[n-1])?.name} 上移`" @click="movePlayer(ids,n-1,-1)">↑</button><button :disabled="n===ids.length" :aria-label="`将 ${person(ids[n-1])?.name} 下移`" @click="movePlayer(ids,n-1,1)">↓</button></div></template><template v-else><span>+</span><small>第 {{pickOrder(ix,n)}} 顺位</small></template></div></section><section class="pool"><div class="poolhead"><div><small>PLAYER POOL</small><h2>选择球员 <span>{{pool.length}} 位可选</span></h2></div><div class="filters"><label class="search-control"><span aria-hidden="true">⌕</span><input v-model="search" aria-label="搜索球员" placeholder="搜索球员"></label><label class="select-control"><span class="sr-only">位置筛选</span><select v-model="position"><option value="全部">选择位置</option><option value="PG">控球后卫 PG</option><option value="SG">得分后卫 SG</option><option value="SF">小前锋 SF</option><option value="PF">大前锋 PF</option><option value="C">中锋 C</option></select></label><label class="select-control"><span class="sr-only">球队筛选</span><select v-model="team"><option value="全部">选择球队</option><option v-for="t in teams" :key="t" :value="t">{{t}}</option></select></label><label class="select-control"><span class="sr-only">排序方式</span><select v-model="sort"><option value="default">默认排序</option><option value="pts">得分排序</option><option value="reb">篮板排序</option><option value="ast">助攻排序</option></select></label></div></div><div v-if="!finished && currentAction.kind==='pick'" class="draft-fit" :class="current==='blue'?'fit-home':'fit-away'"><strong>{{current==='blue'?'主队':'客队'}} · 阵容关注</strong><span v-for="item in currentFit.needs" :key="item">{{item}}</span><small>个人赛季数据推演，仅供参考</small></div><div class="filter-note">五个位置根据 ESPN 的 G / F / C 标签、助攻和身高估算，仅供筛选参考。</div><div v-if="busy" class="thinking">AI 正在{{currentAction.kind==='ban'?'禁用':'选人'}}…</div><div class="grid" :class="{locked:busy||finished}"><p v-if="!pool.length" class="empty-pool">没有符合条件的球员，请调整筛选条件。</p><button v-for="p in pool" :key="p.id" class="player" @click="select(p)"><div class="portrait"><span>{{p.name.split(' ').map(x=>x[0]).slice(0,2).join('')}}</span><img :src="`/headshots/${p.id}.png`" @error="($event.target as HTMLImageElement).style.display='none'; ($event.target as HTMLImageElement).parentElement?.classList.add('portrait-fallback')"></div><b>{{p.name}}</b><small>{{p.team}} · {{p.position}}</small><div class="numbers"><span>{{p.pts?.toFixed(1)}} <small>PTS</small></span><span>{{p.reb?.toFixed(1)}} <small>REB</small></span><span>{{p.ast?.toFixed(1)}} <small>AST</small></span></div></button></div><footer>{{reason || (currentAction?.kind==='ban'&&!finished?'选择一名球员禁用':'选择一名球员加入当前阵容')}} <span>{{error}}</span></footer></section></div></main><div v-if="shareImage" class="overlay share-overlay" role="dialog" aria-modal="true" aria-label="阵容分享卡" @click.self="shareImage=''"> <div class="share-card"><button class="candidate-close" aria-label="关闭分享卡" @click="shareImage=''">✕</button><h2>分享阵容</h2><p>包含双方首发、比赛倾向和你选择的对位</p><label class="share-position">选择对位 <select v-model.number="sharePosition" @change="prepareShare"><option v-for="(label,i) in positionLabels" :key="label" :value="i">{{label}}</option></select></label><img :src="shareImage" alt="双方首发阵容及比赛倾向分享卡"><div class="share-actions"><button class="primary" @click="shareResult">分享图片</button><button @click="downloadShare">保存图片</button></div><small role="status">{{shareMessage}}</small></div></div><div v-if="review || reviewLoading || reviewError" class="overlay" role="dialog" aria-modal="true" aria-label="阵容复盘"><div v-if="reviewLoading" class="review-loading" role="status"><div class="spinner"></div><small>POST-DRAFT ANALYSIS</small><h2>正在分析双方阵容</h2><p>正在整理球员数据和阵容结构，请稍候。</p></div><div v-else-if="reviewError" class="review-loading" role="alert"><h2>复盘暂时不可用</h2><p>{{reviewError}}</p><button class="primary" @click="showReview">重新尝试</button><button class="close" aria-label="关闭" @click="reviewError=''">✕</button></div><div v-else class="modal review-modal"><button class="close" aria-label="关闭复盘" @click="review=null">✕</button><div class="review-heading"><div><small>POST-DRAFT ANALYSIS</small><h1>阵容复盘</h1></div><button class="share-button" @click="prepareShare">分享阵容</button><span class="mode-badge">{{review.mode === 'ai' ? '✦ DeepSeek 分析' : '本地规则复盘'}}</span></div><div class="verdict"><div class="scoreline"><div><small>主队倾向</small><strong>{{review.verdict.blueWinRate}}<sup>%</sup></strong></div><span>VS</span><div><small>客队倾向</small><strong>{{review.verdict.redWinRate}}<sup>%</sup></strong></div></div><div class="scorebar"><span :style="{width:review.verdict.blueWinRate+'%'}"></span></div><p>{{review.verdict.summary}}</p><small>{{review.mode === 'ai' ? '胜率倾向为 DeepSeek 的主观判断，并非统计预测' : '胜率倾向为本地规则的主观估计，并非统计预测'}}</small></div><section class="review-section radar-section"><small>TEAM COMPARISON</small><h2>八维阵容比较</h2><p class="chart-note">{{review.mode === 'ai' ? 'AI 主观评分 / 100，供对比参考' : '本地规则估计，阵容适配为球权和空间的粗略参考，仅供对比'}}</p><div class="radar-layout"><svg class="radar" viewBox="0 0 360 310" role="img" aria-label="主客队八维阵容雷达图"><polygon v-for="level in [20,40,60,80,100]" :key="level" :points="radarPoly(keys.map(()=>level))" class="radar-grid"/><line v-for="(k,i) in keys" :key="k" x1="180" y1="155" :x2="radarPoint(i,100)[0]" :y2="radarPoint(i,100)[1]" class="radar-axis"/><polygon :points="radarPoly(radarValues('home'))" class="radar-home"/><polygon :points="radarPoly(radarValues('away'))" class="radar-away"/><text v-for="(k,i) in keys" :key="k" :x="radarPoint(i,119)[0]" :y="radarPoint(i,119)[1]" text-anchor="middle" dominant-baseline="middle">{{names[i]}}</text></svg><div class="radar-table"><div class="radar-row radar-legend"><span>维度</span><b>主队</b><b>客队</b></div><div v-for="(k,i) in keys" :key="k" class="radar-row"><span>{{names[i]}}</span><b>{{radarValues('home')[i]}}</b><b>{{radarValues('away')[i]}}</b></div></div></div></section><section class="review-section"><small>TEAM FIT</small><h2>球队分析</h2><p class="chart-note">基于球员赛季数据推演阵容分工，不代表实际共同上场效果。</p><div class="team-fit"><article v-for="(x,ix) in [review.home,review.away]" :key="ix" :class="ix ? 'fit-away' : 'fit-home'"><div class="fit-title"><h3>{{ix?'客队':'主队'}}</h3><span>阵容分析</span></div><div class="fit-brief"><div><h4>阵容分工</h4><p>{{(ix ? review.teamAnalysis.away : review.teamAnalysis.home).adaptation || (ix ? review.teamAnalysis.away : review.teamAnalysis.home).ball}}</p></div><div v-for="group in ['strengths','weaknesses']" :key="group"><h4>{{group==='strengths'?'优势':'劣势'}}</h4><ul><li v-for="v in x[group].slice(0,2)" :key="v">{{v}}</li></ul></div><div><h4>极限情境</h4><p>{{(ix ? review.teamAnalysis.away : review.teamAnalysis.home).extreme || '若主要发起点被限制，需观察其他球员能否承担组织任务。'}}</p></div></div><details class="fit-detail"><summary>查看阵容分工参考</summary><p>建议发起：{{(ix ? review.teamAnalysis.away : review.teamAnalysis.home).fit?.creators.join('、') || '数据不足'}}；高负荷：{{(ix ? review.teamAnalysis.away : review.teamAnalysis.home).fit?.high.join('、') || '未达到参考门槛'}}。</p><p>投射：{{(ix ? review.teamAnalysis.away : review.teamAnalysis.home).fit?.shooters.join('、') || '未达到参考门槛'}}；篮板：{{(ix ? review.teamAnalysis.away : review.teamAnalysis.home).fit?.rebounders.join('、') || '未达到参考门槛'}}；盖帽：{{(ix ? review.teamAnalysis.away : review.teamAnalysis.home).fit?.rim.join('、') || '未达到参考门槛'}}。</p><p>无球战术数据缺失：{{(ix ? review.teamAnalysis.away : review.teamAnalysis.home).fit?.missingOffball.join('、') || '无'}}。外线防守和协防仍需观察。</p></details></article></div><div class="fit-comparison evidence-summary"><div class="fit-comparison-head"><div><strong>阵容数据对比</strong><small>本地规则根据五名球员赛季数据估算，0–100 分，与上方 AI 评分口径不同；并非共同上场表现。</small></div><div class="fit-bar-legend"><span>● 主队</span><span>● 客队</span></div></div><div class="scoreboard"><section v-for="group in metricGroups" :key="group.label" class="scoreboard-group"><div class="scoreboard-heading"><span>主队</span><strong>{{group.label}}</strong><span>客队</span></div><div v-for="key in group.keys" :key="key" class="team-metric scoreboard-row" :class="`lead-${metricLead(key)}`"><b class="score-home">{{teamMetricText(teamMetricValue(home,key))}}</b><span class="score-label">{{metricByKey(key).label}}</span><b class="score-away">{{teamMetricText(teamMetricValue(away,key))}}</b></div></section></div><details class="fit-detail"><summary>查看评分依据</summary><p v-for="metric in teamMetrics" :key="metric.key"><b>{{metric.label}}：</b>{{metric.description}}</p><p>分数采用固定区间和简化规则，区间外截断；不同维度不可相加，也不代表经过比赛验证的能力值。</p></details></div></section><section v-if="bpEnabled && bpHighlights.length" class="review-section bp-review"><small>BAN / PICK</small><h2>禁选回顾</h2><p class="chart-note">展示双方每轮综合价值较高的一个禁用；事实与基于数据的阵容推演分别列出，不代表禁用者的真实意图。</p><div class="bp-review-grid"><article v-for="item in bpHighlights" :key="item.key" :class="item.side==='blue'?'bp-review-home':'bp-review-away'"><small>第 {{item.round}} 轮 · {{item.side==='blue'?'主队':'客队'}}禁用</small><strong>{{item.name}}</strong><p><b>事实：</b>{{item.context}}。<template v-if="item.nextPick">对方下一次选择 {{item.nextPick}}。</template></p><p><b>推演：</b>当时需求：{{item.needs}}；被禁球员可能提供 {{item.traits}}。无法判断后续选择是否由这次禁用造成。</p></article></div></section><section class="review-section"><small>HEAD TO HEAD</small><h2>{{review.mode === 'ai' ? '五个位置的模拟对位' : '关键对位'}}</h2><p class="chart-note">按选秀页中双方排定的位置比较；评分按后卫、前锋或中锋组的百分位计算，非官方能力值，实际防守对位可能不同。</p><div class="matchups matchup-comparisons"><article v-for="(m,i) in review.matchups" :key="m.title" class="matchup-card"><div class="matchup-top"><span class="matchup-position">{{positionLabels[i]}}</span><span>2024–26 双赛季</span></div><div class="matchup-players"><div><img :src="`/headshots/${home[i]}.png`" @error="($event.target as HTMLImageElement).style.display='none'"><strong>{{person(home[i])?.name}}</strong><small>主队 · {{person(home[i])?.seasons?.map(s=>s.season).join(' / ')}}</small></div><span>VS</span><div><img :src="`/headshots/${away[i]}.png`" @error="($event.target as HTMLImageElement).style.display='none'"><strong>{{person(away[i])?.name}}</strong><small>客队 · {{person(away[i])?.seasons?.map(s=>s.season).join(' / ')}}</small></div></div><div class="player-radar-layout"><svg class="radar player-radar" viewBox="0 0 360 310" role="img" :aria-label="`${person(home[i])?.name} 与 ${person(away[i])?.name} 的数据雷达图`"><polygon v-for="level in [20,40,60,80,100]" :key="level" :points="playerPoly(metricsForPosition(i).map(()=>level))" class="radar-grid"/><line v-for="(stat,j) in metricsForPosition(i)" :key="stat.key" x1="180" y1="155" :x2="playerPoint(j,100)[0]" :y2="playerPoint(j,100)[1]" class="radar-axis"/><polygon v-if="playerRadarValues(home[i],i).every(v=>v!==null)" :points="playerPoly(playerRadarValues(home[i],i) as number[])" class="player-fill-home"/><polygon v-if="playerRadarValues(away[i],i).every(v=>v!==null)" :points="playerPoly(playerRadarValues(away[i],i) as number[])" class="player-fill-away"/><line v-for="(seg,j) in playerSegments(home[i],i)" :key="`h${j}`" :x1="seg.a[0]" :y1="seg.a[1]" :x2="seg.b[0]" :y2="seg.b[1]" class="player-line-home"/><line v-for="(seg,j) in playerSegments(away[i],i)" :key="`a${j}`" :x1="seg.a[0]" :y1="seg.a[1]" :x2="seg.b[0]" :y2="seg.b[1]" class="player-line-away"/><circle v-for="(v,j) in playerRadarValues(home[i],i)" v-show="v!==null" :key="`hc${j}`" :cx="playerPoint(j,v ?? 0)[0]" :cy="playerPoint(j,v ?? 0)[1]" r="2.5" class="player-dot-home"/><circle v-for="(v,j) in playerRadarValues(away[i],i)" v-show="v!==null" :key="`ac${j}`" :cx="playerPoint(j,v ?? 0)[0]" :cy="playerPoint(j,v ?? 0)[1]" r="2.5" class="player-dot-away"/><text v-for="(stat,j) in metricsForPosition(i)" :key="stat.key" :x="playerPoint(j,119)[0]" :y="playerPoint(j,119)[1]" text-anchor="middle" dominant-baseline="middle">{{stat.label}}</text></svg><div class="radar-table player-stats"><div class="radar-row radar-legend"><span>模型评分 / 100</span><b>主队</b><b>客队</b></div><div v-for="stat in metricsForPosition(i)" :key="stat.key" class="radar-row"><span :title="stat.description">{{stat.label}} ⓘ</span><b>{{statText(matchupValue(home[i],stat,i),stat)}}<small v-if="matchupValue(home[i],stat,i)===null" class="missing-reason">{{missingReason(home[i],stat,i)}}</small></b><b>{{statText(matchupValue(away[i],stat,i),stat)}}<small v-if="matchupValue(away[i],stat,i)===null" class="missing-reason">{{missingReason(away[i],stat,i)}}</small></b></div></div></div><details v-if="i===4" class="tracking-detail"><summary>查看内线战术与篮下防守样本</summary><div v-for="(id,sideIndex) in [home[i],away[i]]" :key="id"><b>{{sideIndex?'客队':'主队'}} · {{person(id)?.name}}</b><p>内线战术：<template v-if="person(id)?.insideSamples?.length"><span v-for="sample in person(id)?.insideSamples" :key="sample.season">{{sample.season-1}}–{{String(sample.season).slice(-2)}} {{sample.possessions}} 回合；</span></template><template v-else>暂无足够数据</template></p><p>篮下防守：<template v-if="person(id)?.rimSamples?.length"><span v-for="sample in person(id)?.rimSamples" :key="sample.season">{{sample.season-1}}–{{String(sample.season).slice(-2)}} {{sample.attempts}} 次出手，命中率 {{(sample.allowed*100).toFixed(1)}}%，参照 {{(sample.baseline*100).toFixed(1)}}%；</span></template><template v-else>暂无足够数据</template></p></div></details><details class="metric-detail"><summary>查看八维数据口径和样本</summary><div v-for="stat in metricsForPosition(i)" :key="stat.key"><p><b>{{stat.label}}</b>：{{stat.description}}</p><p v-for="(id,si) in [home[i],away[i]]" :key="id" class="metric-evidence">{{si ? '客队' : '主队'}}：<template v-if="!stat.components.length">暂无数据</template><template v-else><span v-for="part in metricSources(person(id),stat)" :key="part.key">{{part.label}} {{part.value===null?'暂无数据':part.value.toFixed(3)}}<template v-if="part.samples?.length">（<span v-for="sample in part.samples" :key="sample.season">{{sample.season-1}}–{{String(sample.season).slice(-2)}}：{{sample.possessions != null ? sample.possessions + ' 回合' : sample.minutes != null ? sample.gp + ' 场 / ' + Math.round(sample.minutes) + ' 分钟' : sample.attempts + ' 次防守出手'}} </span>）</template>；</span></template></p></div></details><details class="season-detail"><summary>查看各赛季原始数据</summary><div class="season-detail-grid"><div v-for="(id,sideIndex) in [home[i],away[i]]" :key="id"><strong>{{sideIndex ? '客队' : '主队'}} · {{person(id)?.name}}</strong><div v-for="season in person(id)?.seasons" :key="season.season" class="season-line"><b>{{season.season}}</b><span>出场 {{season.gp}} · 得分 {{season.pts.toFixed(1)}} · 篮板 {{season.reb.toFixed(1)}} · 助攻 {{season.ast.toFixed(1)}}</span><span>盖帽 {{season.blk.toFixed(1)}} · 抢断 {{season.stl.toFixed(1)}} · 失误 {{season.tov.toFixed(1)}} · PER {{season.per.toFixed(1)}} · TS {{(season.points/(2*(season.fga+.44*season.fta))*100).toFixed(1)}}%</span></div></div></div></details><div class="matchup-analysis"><small>对位解读</small><p>{{m.analysis}}</p></div></article></div><p class="chart-note matchup-note">各位置使用不同的八维模型评分；各项基础数据在当前球员池中按百分位换算后加权，分数不是官方能力值。失误越少越靠外。带“代理”的维度仅使用近似数据，并非对实际能力的直接测量；战术效率和篮下防守使用可取得的赛季追踪数据；样本不足的数据不绘制。比较基准为 ESPN 的 G、F、C 球员组：PG/SG 对比后卫，SF/PF 对比前锋，C 对比中锋。并非精确的五位置分组。点击“查看八维数据口径”了解具体计算方法。2024–25 基础权重 35%，2025–26 为 65%；少于 20 场降低权重，仅一个赛季则使用该赛季。</p></section><section class="review-section"><small>KEYS TO THE GAME</small><h2>获胜关键</h2><ul class="factors"><li v-for="k in review.keyFactors" :key="k">{{k}}</li></ul></section><p class="review-disclaimer">护框为盖帽、篮板和身高的代理指标；持球负荷不是官方使用率。{{review.mode === 'ai' ? '模型生成内容仅作参考。' : ''}}</p></div></div></div></template>